815: func (d *Driver) registerFunction(
816: 	zFuncName string,
817: 	impl *FunctionImpl,
818: ) error {
819: 	d.mu.Lock()
820: 	defer d.mu.Unlock()
821: 
822: 	if d.udfs == nil {
823: 		d.udfs = map[string]*userDefinedFunction{}
824: 	}
825: 	if _, ok := d.udfs[zFuncName]; ok {
826: 		return fmt.Errorf("a function named %q is already registered", zFuncName)
827: 	}
828: 
829: 	// dont free, functions registered on the driver live as long as the program
830: 	name, err := libc.CString(zFuncName)
831: 	if err != nil {
832: 		return err
833: 	}
834: 
835: 	var textrep int32 = sqlite3.SQLITE_UTF8
836: 
837: 	if impl.Deterministic {
838: 		textrep |= sqlite3.SQLITE_DETERMINISTIC
839: 	}
840: 
841: 	udf := &userDefinedFunction{
842: 		zFuncName: name,
843: 		nArg:      impl.NArgs,
844: 		eTextRep:  textrep,
845: 	}
846: 
847: 	if impl.Scalar != nil {
848: 		xFuncs.mu.Lock()
849: 		id := xFuncs.ids.next()
850: 		xFuncs.m[id] = xFuncEntry{fn: impl.Scalar, volatile: impl.VolatileArgs}
851: 		xFuncs.mu.Unlock()
852: 
853: 		udf.scalar = true
854: 		udf.pApp = id
855: 	} else {
856: 		xAggregateFactories.mu.Lock()
857: 		id := xAggregateFactories.ids.next()
858: 		xAggregateFactories.m[id] = xAggregateFactoryEntry{factory: impl.MakeAggregate, volatile: impl.VolatileArgs}
859: 		xAggregateFactories.mu.Unlock()
860: 
861: 		udf.pApp = id
862: 	}
863: 
864: 	d.udfs[zFuncName] = udf
865: 
866: 	return nil
867: }
